\n","INSERT [dbo].[shifts] ([branch_id], [id], [shift_date], [staff_id], [shift_type]) VALUES (7, 913, CAST(N'2026-07-09' AS Date), 62, N'MORNING')\r\n","INSERT [dbo].[shifts] ([branch_id], [id], [shift_date], [staff_id], [shift_type]) VALUES (7, 914, CAST(N'2026-07-09' AS Date), 63, N'MORNING')\r\n","INSERT [dbo].[shifts] ([branch_id], [id], [shift_date], [staff_id], [shift_type]) VALUES (7, 915, CAST(N'2026-07-09' AS Date), 64, N'MORNING')\r\n","INSERT [dbo].[shifts] ([branch_id], [id], [shift_date], [staff_id], [shift_type]) VALUES (7, 916, CAST(N'2026-07-10' AS Date), 61, N'MORNING')\r\n","INSERT [dbo].[shifts] ([branch_id], [id], [shift_date], [staff_id], [shift_type]) VALUES (7, 917, CAST(N'2026-07-10' AS Date), 62, N'MORNING')\r\n","INSERT [dbo].[shifts] ([branch_id], [id], [shift_date], [staff_id], [shift_type]) VALUES (7, 918, CAST(N'2026-07-10' AS Date), 63, N'MORNING')\r\n","INSERT [dbo].[shifts] ([branch_id], [id], [shift_date], [staff_id], [shift_type]) VALUES (7, 919, CAST(N'2026-07-10' AS Date), 64, N'MORNING')\r\n","SET IDENTITY_INSERT [dbo].[shifts] OFF\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LAPTOP-O4IB8J3G-AnhBi\\SQLEXPRESS01']/Database[@Name='care_bike']/Table[@Name='shifts' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[spare_parts]"],"metadata":{"urn":"Server[@Name='LAPTOP-O4IB8J3G-AnhBi\\SQLEXPRESS01']/Database[@Name='care_bike']/Table[@Name='spare_parts' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["SET IDENTITY_INSERT [dbo].[spare_parts] ON \r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 8, CAST(1890000.00 AS Numeric(15, 2)), N'Vỏ Michelin City Grip 2 rất phù hợp với điều kiện ở Việt Nam bởi thiết kế nhiều rảnh gai sâu, ở phiên bản City Grip 2 này được cải tiển thêm nhiều chấm gai nhỏ, dài giúp thoáng nước cực tốt mà độ bền vẫn giữ được lâu.\r\nMichelin City Grip 2 được sản xuất tại Châu Âu, với nhiều rãnh nhỏ trên bề mặt lốp sẽ đảm bảo việc di chuyển ở đường trơn, ôm cua gấp được an toàn hơn.\r\nVỏ Michelin City Grip 2 size 120/80-16 dành cho bánh sau xe SH.', N'/images/401a67b6-13a5-487a-b330-580f2c4c728b_vo-michelin-city-grip-2-12080-16.jpg', N'Vỏ Michelin City Grip 2 size 120/80-16')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 9, CAST(480000.00 AS Numeric(15, 2)), N'Motul 300V Racing/Road 10W40 1L nhớt chất lượng cao dành cho xe mô tô phân khối lớn, xe côn tay, xe số,...\r\nNhớt Motul 300V 10W40 1L tối ưu hóa công suất động cơ và bảo vệ động cơ một cách hoàn hảo.\r\n- Dầu nhớt tổng hợp 100% Synthese.\r\n- Tiêu chuẩn: API SN, JASO MA.\r\n- Dung tích: 1 lít', N'/images/5df07472-de2b-409e-af52-ba96eb03e102_Motul 300V 10W40.jpg', N'Nhớt Motul 300V Racing/Road 10W40 1L')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 10, CAST(4400000.00 AS Numeric(15, 2)), N'- Phuộc RCB Flow Pro chính hãng dành cho xe Honda AB các đời, có chân tăng chỉnh chiều cao phù hợp cho các loại xe AB, gắn như zin có bình dầu nằm trên, thiết kế hiện đại, vận hành êm ái và bền bỉ.\r\n- Phuộc sau RCB Flow Pro bình dầu với núm tăng chỉnh độ hồi rebound ngay chân phuộc và núm tăng độ cứng (comp) phù hợp cho mọi địa hình và tải nặng.\r\n- Phuộc RCB Flow Pro cho Honda AB cao 320mm. Bảo hành: 12 tháng chính hãng RCB.', N'/images/0e6bff17-864a-44a3-8854-932a1b70f424_rcb-flow-pro-cho-air-blade.jpg', N'Phuộc RCB Flow Pro cho Air Blade')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 11, CAST(305000.00 AS Numeric(15, 2)), N'Dây Curoa Michelin cho Yamaha Nozza 2015, sản phẩm mới thương hiệu Michelin có cấu tạo mặt trong viền Cacbon tăng 30% công suất.\r\nTÍNH NĂNG NỔI BẬT CỦA SẢN PHẨM:\r\n- Nhiệt độ sử dụng: -40 ~ 130 độ C.\r\n- Độ cứng và độ dẻo tốt.\r\n- Độ chống nhão cao, hạn chế mài mòn tốt.\r\n- Chuyển động ổn định, ít tiếng ồn.\r\n- Ít lão hóa, tuổi thọ cao.\r\nDây Curoa Michelin cho Yamaha Nozza là sản phẩm chính hãng của thương hiệu Michelin quá quen thuộc với người tiêu dùng.', N'/images/af3e7d7e-d079-43bf-9488-972b4ac4887e_6463b325-795f-416f-a70c-2a61eb598fdb_day-curoa-michelin-cho-yamaha-nozza.png', N'Dây Curoa Michelin cho Yamaha Nozza')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 12, CAST(184000.00 AS Numeric(15, 2)), N'Motul Scooter Power LE 5W40 0.8L nhớt xe tay ga đời mới của tập đoàn nhớt Motul. Nhớt kiểm soát tốt cặn trong piston, chống mài mòn, chống ăn mòn cực kỳ hiệu quả với khả năng tẩy rửa tuyệt hảo giúp động cơ luôn được giữ sạch.\r\n- Dầu nhớt tổng hợp 100%.\r\n- Tiêu chuẩn: API SP /SN/SM, JASO MB.\r\n- Dung tích: 800 ml', N'/images/10604ff5-8bd3-4fab-a4e7-9506048fe351_cf7cfa75-950a-48b4-a696-ef0c5ed2c205_motul 5w40 .jpg', N'Nhớt Motul Scooter Power LE 5W40 0.8L')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 13, CAST(710000.00 AS Numeric(15, 2)), N'- Vỏ Deli SB 170 Power Storm XP 100/80-17 sản xuất tại Indonesia.\r\n- Vỏ Deli SB 170 Power Storm XP 100/80-17 với thiết kế rãnh đôi ở giữa, gai dày và sâu 2 bên giúp vỏ bám cực tốt trên đường ướt.\r\n- Vỏ Deli SB 170 Power Storm XP 100/80-17 gắn được các xe: Exciter 13 hoặc Winner, Exciter 150 muốn đi bánh nhỏ.\r\n710.000', N'/images/bcbfc777-edf2-4474-9933-85d69d8a57ac_91c5dd29-32da-4991-b51d-fec73288b11a_vo-xe-deli-sb-170-power-storm-xp-10080-17.jpg', N'Vỏ xe Deli SB 170 Power Storm XP 100/80-17')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 14, CAST(135000.00 AS Numeric(15, 2)), N'- Nhớt Fuchs Silkolene Scoot 4 MB 10W40 0.8L dành riêng cho xe tay ga, mang lại trải nghiệm lái êm ái và thoải mái vượt trội, giúp động cơ được bảo vệ tối đa, tối ưu hiệu suất và tiết tiết kiệm nhiên liệu.\r\n- Nhớt Fuchs Silkolene Scoot 4 MB 10W40 0.8L là nhớt bán tổng hợp kết hợp phụ gia cao cấp. Thời gian đi khoảng 1.200-1.500 km mới phải thay lại.\r\n- Xuất xứ: Đức, sản xuất tại Việt Nam. Dung tích: 800 ml', N'/images/2295c9a1-6ae0-43aa-98b7-c1201151aba0_nhot-fuchs-silkolene-scoot-4-mb-10w40.jpg', N'Nhớt Fuchs Silkolene Scoot 4 MB 10W40 0.8L')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 15, CAST(275000.00 AS Numeric(15, 2)), N'- Nhớt Repsol Racing 10W40 với công nghệ hiện đại, bảo vệ và vận hành tối ưu, giúp kéo dài tuổi thọ động cơ.\r\n- Repsol Racing 10w40 khả năng thích nghi cao, độc đáo, phù hợp với hầu hết các loại xe và các loại động cơ 4 thì. Nhớt giúp giảm nhiệt tốt, cải thiện tốt sức mạnh và độ bền của động cơ. Loại nhớt này mang lại khả năng kiểm soát tốt hơn với sự sang số êm hơn và trải nghiệm lái xe đầy hứng thú nhờ giảm tiếng ồn và rung động.\r\n- Nhớt tổng hợp 100%\r\n- Cấp hiệu năng: API SN\r\n- Dung tích: 1 lít', N'/images/393f6d67-687d-446b-94fb-6da0429b3949_nhot-repsol-racing-10w40-1lit.jpg', N'Nhớt Repsol Racing 10W40 1L')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 16, CAST(195000.00 AS Numeric(15, 2)), N'Nhớt Repsol MXR Platinum 10W40 - sản phẩm dành riêng cho các dòng xe số ở thị trường Châu Á, là loại nhớt tổng hợp mạnh mẽ và vượt trội cho động cơ đạt công xuất tối đa. Với công nghệ hiện đại, sản phẩm sẽ mang lại sự bảo vệ và vận hành tối ưu, giúp kéo dài tuổi thọ động cơ.\r\n- Tiêu chuẩn: API SN, Jaso MA2.\r\n- Nhớt tổng hợp hoàn toàn: Fully Synthetic.\r\n- Dung tích: 1 lít', N'/images/8d80f24a-f7cc-4e2d-a57f-003ea163b1b1_nhot-repsol-mxr-platium-10w40.jpg', N'Nhớt Repsol MXR Platinum 10W40 1L')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 17, CAST(155000.00 AS Numeric(15, 2)), N'- Nhớt Fuchs Silkolene Super 4 10W40 1L là nhớt bán tổng hợp cao cấp được thiết kế để sử dụng cho cả xe máy trên đường trường và đường địa hình. Với đặc tính sang số mượt mà, chống mài mòn, tăng tuổi thọ cho động cơ.\r\n- Thời gian đi khoảng 1.000 - 1.200 km mới phải thay lại.\r\n- Cấp nhớt: 10W40. Jaso MA2 - API: SN. Nhớt bán tổng hợp. Xuất xứ: Indonesia.\r\n- Dung tích: 1 lít', N'/images/f0cf8ac4-c846-47a0-8d8c-84cd43118713_nhot-fuchs-silkolene-super-4-10w40-1l.jpg', N'Nhớt Fuchs Silkolene Super 4 10W40 1L')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 18, CAST(165000.00 AS Numeric(15, 2)), N'- Nhớt Castrol Activ Scooter 10W40 1L dành cho xe tay ga, là nhớt bán tổng hợp với cấp nhớt API SN, với khả năng bảo vệ - 3X Protection cùng Công nghệ Actibond giúp:\r\n+ Chống mài mòn tốt hơn 50% khi khởi động.\r\n+ Chống cặn, làm sạch động cơ vượt trội trong quá trình vận hành.\r\n+ Bảo vệ chống ăn mòn xuất sắc ngay cả khi đã dừng máy.\r\n- Tiêu chuẩt: Jaso MB - API SN\r\n- Dung tích 1 lít.', N'/images/250240ef-70e9-4cc8-bac5-3617062a1575_nhot-castrol-activ-scooter-10w40-.jpg', N'Nhớt Castrol Activ Scooter 10W40 1L dành cho xe tay ga')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 19, CAST(520000.00 AS Numeric(15, 2)), N'- Nhớt Castrol Power 1 Ultimate Superbike 10W50 dành cho các dòng xe số phân khối lớn các hãng như: Ducati, Aprilia, Harley Davidson... với khuyến cáo cấp nhớt W50, sản phẩm công nghệ Ester cao cấp được hoàn thiện cùng công thức 5 trong 1 giúp động cơ đạt hiệu suất cực đỉnh và tăng tốc tối ưu:\r\n1. Tăng tốc vượt trội\r\n2. Bảo vệ tuyệt đỉnh\r\n3. Vận hành êm ái\r\n4. Giải nhiệt hiệu quả\r\n5. Công suất tối đa\r\n- Nhớt Castrol Power 1 Ultimate Superbike 10W50 1L là nhớt tổng hợp toàn phần Ester, sản phẩm cao cấp của Castrol.\r\n- Tiêu chuẩn Jaso MA2\r\n- Dung tích 1 lít', N'/images/2b38477e-5333-461a-b792-cbf1973c54e3_nhot-castrol-power-1-ultimate-superbike-10w50.jpg', N'Nhớt Castrol Power 1 Ultimate Superbike 10W50 dành cho các dòng xe số phân khối lớn')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 20, CAST(205000.00 AS Numeric(15, 2)), N'- Shell Advance Ultra Scooter 5W40 0,8L, dầu nhớt tổng hợp cao cấp dành cho tất cả các loại xe tay ga 4 thì đời mới. Bảo vệ tối ưu và khả năng vận hành đáng tin cậy, tăng độ ổn định trượt cao giúp giảm rung động và giảm tiếng ồn.\r\n- Thông số kỹ thuật: nhớt tổng hợp 100%\r\n- Tiêu chuẩn API SP, Jaso MB.\r\n- Dung tích: 800 ml', N'/images/ad7d4260-fd61-4a63-8a8f-97f1505994a2_nhot-shell-advance-ultra-scooter-5w40.jpg', N'Nhớt Shell Advance Ultra Scooter 5W40 0,8L')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (4, 21, CAST(165000.00 AS Numeric(15, 2)), N'- Shell Advance 4T AX7 10W40 Synthetic Based nhớt xe máy chuyên dụng dành cho xe số 4 thì của tập đoàn nhớt Shell.\r\n- Shell Advance 4T AX7 10W40 Synthetic Based được ứng dụng nhiều công nghệ nhớt tiên tiến hiện đại giúp bảo vệ động cơ xe số tốt trong điều kiện đường xá và khí hậu tại Việt Nam.\r\n- Nhớt bán tổng hợp.\r\n- API SN, JASO MA2.\r\n- Dung tích: 1 lít', N'/images/72385204-f5f3-437d-9b53-b6a6b1a76937_nhot-shell-advance-4t-ax7-10w40.jpg', N'Nhớt Shell Advance 4T AX7 10W40 Synthetic Based 1L')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 22, CAST(2350000.00 AS Numeric(15, 2)), N'- Phuộc trước LCM ty bạc cho Honda Winner đời đầu (không phải Winner X) mang thiết kế với ngoại hình to lớn đầy cứng cáp, phuộc LCM nhìn bề ngoài tuy rất to chắc nhưng khi vận hành thì độ nhún rất êm nhờ thiết kế đường dầu mới, không sàn lắc.\r\n- Phuộc LCM quan trọng là ráp như zin cho Winner không cần chế cháo bất kì chi tiết nào dù là nhỏ.\r\n- Phuộc LCM sản xuất tại Taiwan, bảo hành 12 tháng.', N'/images/17bba731-cf15-4f2d-baad-5e419112dd2f_phuoc-truoc-lcm-ty-bac-cho-honda-winner.jpg', N'Phuộc trước LCM ty bạc cho Honda Winner')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 23, CAST(520000.00 AS Numeric(15, 2)), N'- Bố thắng trước Honda SH 2017 - 2025 (ABS) có độ cứng vững cao, chịu được lực phanh lớn, đảm bảo phanh hiệu quả và không gây bó kẹt.\r\n- Chống bào mòn, không gây tiếng kêu.\r\n- Với độ bám tốt, lực bám đồng đều ở bề mặt đáp ứng rất tốt cho mọi điều kiện vận hành của xe. Đặc biệt là xe di chuyển ở các thành phố lớn, khi lên ga xuống ga và phanh nhiều nhiệt sinh ra lớn dẫn đến má phanh đĩa bị mài mòn rất nhanh.', N'/images/b5b787f0-81f2-439e-872b-633efd4e9a48_bo-thang-truoc-honda-sh.png', N'Bố thắng trước Honda SH 2017 - 2025 (ABS)')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 24, CAST(145000.00 AS Numeric(15, 2)), N'Bố thắng đĩa AB 110 Fi/ 125, Lead, Vision, Vario, Click...\r\nBố thắng Honda có độ cứng vững cao, chịu được lực phanh lớn, đảm bảo phanh hiệu quả và không gây bó kẹt.\r\nChống bào mòn, không gây tiếng kêu.\r\nVới độ bám tốt, lực bám đồng đều ở bề mặt đáp ứng rất tốt cho mọi điều kiện vận hành của xe. Đặc biệt là xe di chuyển ở các thành phố lớn, khi lên ga xuống ga và phanh nhiều nhiệt sinh ra lớn dẫn đến má phanh đĩa bị mài mòn rất nhanh.', N'/images/4f34c686-70bb-4e63-a89f-b612f7336f5d_bo-thang-dia-ab-110-fi-125-lead.jpg', N'Bố thắng đĩa AB 110 Fi/ 125, Lead')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 25, CAST(370000.00 AS Numeric(15, 2)), N'- Bộ nhông sên dĩa Pro-Bike cho Exciter 135 14T - 39T - 428HS (sên tán đúc 10ly, 124 mắc).\r\n- Nhông dĩa Pro-Bike thiết kế mới đẹp hơn và có độ bền từ 20.000 km - 25.000 km tùy theo cách chạy ổn định của người lái và quá trình bảo dưỡng vệ sinh, bôi trơn định kỳ.\r\n- Sên Pro-Bike 428HS được sản xuất tại Thái Lan.', N'/images/ef62b1be-1edc-4ee6-a2ee-496e3813d65d_bo-nhong-sen-dia-pro-bike-cho-exciter-135-14t-39t.jpg', N'Bộ nhông sên dĩa Pro-Bike cho Exciter 135 14T - 39T - 428HS (sên tán đúc)')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 26, CAST(330000.00 AS Numeric(15, 2)), N'- Sên vàng Recto 428SB-124L, sên bản 9ly dài 124 mắc, thương hiệu nhông sên dĩa Recto gẩn đây đã quên thuộc với nhiều anh em Biker, giá thành vô cùng hợp lí so với các dòng sên DID.\r\n- Sên vàng Recto 428SB-124L hàng chính hãng sản xuất tại Malaysia.\r\n- Sên vàng Recto 428SB-124L dài 124 gắn vừa các loại xe côn tay thể thao từ 150cc trở xuống.', N'/images/c2128a99-54c3-4f5a-9a71-a573259b8df7_sen-vang-recto-428sb-124l.jpg', N'Sên vàng Recto 428SB-124L')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 27, CAST(2240000.00 AS Numeric(15, 2)), N'Mâm RCB 5 cây chính hãng cho Vario, Click, hàng khá hot trên thị trường, thiết kế bản nhỏ, 5 cây mạnh mẽ dành cho dòng xe tay ga nhỏ. Hàng RCB chất lượng tốt đã được nhiều biker tin dùng.\r\nMâm 5 cây RCB chính hãng cho Vario, Click có bản mâm nhỏ thông số là: 1.4 - 1.6, mâm có màu vàng.\r\nMâm 5 cây RCB là hàng chính hãng RCB được bảo hành chính hãng 1 năm.', N'/images/856e5405-382b-4c33-a5c5-fce7ccad5490_mam-rcb-5-cay-cho-vario-click-125150.jpg', N'Mâm RCB 5 cây cho Vario, Click 125/150 chính hãng (01S0403G)')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 28, CAST(4250000.00 AS Numeric(15, 2)), N'Mâm RCB CT600 cao cấp dành cho Vario 125/150, Click 125/150.\r\n- Size mâm trước 4 lỗ size 1.85×14, mâm sau thắng đùm 2.15×14.\r\n- Gia công CNC, bề mặt chắc chắn.\r\n- Thiết kế 6 cây xéo tạo hiệu ứng nổi bật khi xe di chuyển.\r\n- Kết cấu cứng cáp, phù hợp di chuyển hằng ngày.\r\n- Lựa chọn màu sắc: Đen – Bạc. Hàng chính hãng RCB. Bảo hành 12 tháng.', N'/images/7a0342a0-562e-4cc9-99e6-1a76126d07e4_mam-rcb-ct600-cho-vario-150160-1-dia-click.jpg', N'Mâm RCB CT600 cho Vario 125/150, Click 125/150 (01S0512B / 01S0512S)')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (5, 29, CAST(910000.00 AS Numeric(15, 2)), N'Dây Curoa Michelin cho SH350i.\r\nDây curoa mẫu mới thương hiệu Michelin mặt trong viền Cacbon tăng 30% công suất.\r\nTÍNH NĂNG NỔI BẬT CỦA SẢN PHẨM:\r\n- Nhiệt độ sử dụng: -40 ~ 130 độ C.\r\n- Độ cứng và độ dẻo tốt.\r\n- Độ chống nhão cao, hạn chế mài mòn tốt.\r\n- Chuyển động ổn định, ít tiếng ồn.\r\n- Ít lão hóa, tuổi thọ cao.', N'/images/8d3a1589-cea7-4dba-b130-cb94f0d65b03_day-curoa-michelin-cho-sh350i-.jpg', N'Dây Curoa Michelin cho SH350i')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 30, CAST(518000.00 AS Numeric(15, 2)), N'- Vỏ Deli SB 170 Power Storm XP 90/90-14 sản xuất tại Indonesia.\r\n- Vỏ Deli SB 170 Power Storm XP 90/90-14 với thiết kế rãnh đôi ở giữa, gai dày và sâu 2 bên giúp vỏ bám cực tốt trên đường ướt.\r\n- Vỏ Deli SB 170 Power Storm XP 90/90-14 gắn được các xe Vario, AB, Vision...', N'/images/63348274-5cf8-4350-b92f-20ef3a2a904a_vo-xe-deli-sb-170-power-storm-xp.png', N'Vỏ xe Deli SB 170 Power Storm XP 90/90-14')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 31, CAST(745000.00 AS Numeric(15, 2)), N'Lốp Michelin Pilot Moto GP 80/90-14 - 90/90-14 dành cho xe Air Blade, Vision, Vario, Click Thái, Genio, Beat...các đời.\r\nLốp Michelin Pilot Moto GP lần đầu tiên Michelin áp dụng công nghệ vỏ của đường đua mini cho dòng xe phổ thông. Cho hiệu suất bám đường vượt trội. Với thiết kế đậm chất thể thao, độc đáo, được nhiều khách hàng đánh giá rất cao.\r\nVỏ Michelin Moto GP 80/90-14 - 90/90-14 được nhập từ chính hãng Michelin Thái Lan.', N'/images/2444f4c6-954e-473b-91b5-c2f1c648e11e_lop-michelin-pilot-moto-gp.jpg', N'Lốp Michelin Pilot Moto GP  90/90-14')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 32, CAST(640000.00 AS Numeric(15, 2)), N'Lốp Pirelli Angel Scooter 90/80-14 - 100/80-14 dành cho xe Air Blade, Vario, Click Thái...các đời.\r\nChất lượng lốp Pirelli Angel Scooter đã được nhiều anh em trải nghiệm và đánh giá khá cao\r\nVỏ Pirelli Angel Scooter được nhắc đến với độ bền và cao su cao cấp, giúp xe bám đường cực tốt, an toàn khi vào cua, thoát nước cực tốt khi đi mưa.\r\nLốp Pirelli Angel Scooter 90/80-14 - 100/80-14, thương hiệu nổi tiếng từ Italy được sản xuất tại Indonesia.', N'/images/7f6a2ed5-9900-438f-b06e-b39c0a4f6399_lop-pirelli-angel-scoote.jpg', N'Lốp Pirelli Angel Scooter (90/80-14 - 100/80-14)')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 33, CAST(1650000.00 AS Numeric(15, 2)), N'Vỏ xe Pirelli 120/70-17 Diablo Rosso Sport, thương hiệu nổi tiếng từ Italy được sản xuất tại Indonesia. Chất lượng Pirelli đã được nhiều anh em trải nghiệm và đánh giá khá cao, đặc biệt gai mới Diablo Rosso Sport thiết kế các rãnh thoát nước kiểu Flash nhìn rất đẹp, đậm chất thể thao.\r\nVỏ Pirelli Diablo Rosso Sport được nhắc đến với độ bền và cao su cao cấp, giúp xe bám đường cực tốt, an toàn khi vào cua, thoát nước cực tốt khi đi mưa.\r\nVỏ Pirelli 120/70-17 Diablo Rosso Sport gắn được các loại xe số côn tay thể thao: Exciter 150, Winner, TFX, CBR150, CB150, R15....', N'/images/4591ed73-a3b1-42ae-8d38-26f632bce102_vo-pirelli-12070-17-diablo-rosso-sport-.jpg', N'Vỏ Pirelli 120/70-17 Diablo Rosso Sport')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 34, CAST(1207000.00 AS Numeric(15, 2)), N'- Vỏ xe Dunlop 140/70-14 Scoot Smart 2 dành cho Yamaha NVX, thương hiệu Dunlop đã quá quen thuộc với người tiêu dùng Việt Nam với chất lượng bám đường tốt kể cả trên đường mưa, ẩm ướt...Scoot Smart 2 được cải tiến từ mã gai Scoot Smart giúp xe bám đường tốt hơn bởi nhiều rảnh gai và trông sẽ đẹp hơn đời trước\r\n- Vỏ Dunlop Scoot Smart 2 140/70-14 cho xe NVX được sản xuất tại Indonesia.', N'/images/a936a7db-0519-4573-9749-8b172e92e0ee_vo-dunlop-14070-14-scoot-smart-2.jpg', N'Vỏ Dunlop 140/70-14 Scoot Smart 2')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 35, CAST(5800000.00 AS Numeric(15, 2)), N'Vỏ xe Dunlop D451 zin theo xe Honda Sh Ý, gắn được cho SHVN được coi là mẫu vỏ xe tốt hiện nay do khả năng bám đường cực tốt an toàn tuyệt đối khi lưu thông trên đường theo tiêu chuẩn Châu Âu cùng với đó là sự êm ái, dễ chịu cho người lái xe khi đi trên những quãng đường dài hay đường xấu, ghồ ghề.\r\nThông số vỏ: trước 100/80-16 và sau 120/80-16.\r\nVỏ Dunlop D451 được sản xuất tại Slovenia', N'/images/6c06bef0-b020-46fb-9ddc-a7f790afd568_cap-vo-dunlop-d451-zin-theo-xe-sh-y.jpg', N'Cặp vỏ Dunlop D451 zin theo xe SH ý')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 36, CAST(675000.00 AS Numeric(15, 2)), N' Lốp Maxxis CT1 110/70-12 - 120/70-12 dành cho xe Vespa Sprint i-Get, Primavera iGet, MSX125, Grande... các đời.\r\n- Maxxis là thương hiệu quá quen thuộc với chất lượng tốt, giá cả phải chăng, hợp với túi tiền của người tiêu dùng Việt Nam.\r\n- Lốp Maxxis CT1 110/70-12 cho xe Grande, Vespa với mẫu gai hoàn toàn mới nhìn rất đẹp, cao su dày dặn, độ bám đường ổn định trên cả đường khô và ướt.', N'/images/979d06dc-dab8-4c74-ad29-a8749f956952_lop-maxxis-ct1-cho-grande-vespa-c.jpg', N'Lốp Maxxis CT1 cho Grande, Vespa 110/70-12')\r\n","INSERT [dbo].[spare_parts] ([category_id], [id], [price], [description], [image_url], [name]) VALUES (6, 37, CAST(490000.00 AS Numeric(15, 2)), N'- Vỏ Maxxis 100/90-10 với gai MA-WGV không ruột đã quá quen thuộc với khách hàng tại Việt Nam, với thiết kế hoa văn đặc biệt:\r\n- Rãnh chính trung tâm hình chữ S giúp nâng cao tính năng dẫn hướng, kiểm soát tốc độ lái và khả năng thoát nước vượt trội.\r\n- Rãnh phụ vuốt thú tăng tính bám đường ngay cả với góc nghiêng tối đa khi vào khúc cua. Kết hợp cùng các rãnh nhỏ dạng sợi tăng tốc độ cho lốp tốt hơn.\r\n- Thiết kế Sipe bạch tuộc hút nước có hiệu quả phá vỡ màng nước, tăng cảm giác tiếp xúc mặt đường ướt, phù hợp cho mọi điều kiện thời tiết, giá cả lại khá phù hợp.\r\n- Vỏ Maxxis 100/90-10 gai MA-WGV gắn cho bánh sau xe Lead, SCR, Latte, Acruzo, Elizabeth, Spacy', N'/images/ce8dc660-1515-4aba-8216-58b46da0cae3_vo-maxxis-10090-10-gai-ma-wgv-.jpg', N'Vỏ Maxxis 100/90-10 gai MA-WGV')\r\n","SET IDENTITY_INSERT [dbo].[spare_parts] OFF\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LAPTOP-O4IB8J3G-AnhBi\\SQLEXPRESS01']/Database[@Name='care_bike']/Table[@Name='spare_parts' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[staffs]"],"metadata":{"urn":"Server[@Name='LAPTOP-O4IB8J3G-AnhBi\\SQLEXPRESS01']/Database[@Name='care_bike']/Table[@Name='staffs' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["SET IDENTITY_INSERT [dbo].[staffs] ON \r\n","INSERT [dbo].[staffs] ([branch_id], [id], [phone], [staff_code], [full_name]) VALUES (1, 1, N'0937211264', N'CBS-0001', N'Eric Brown')\r\n","INSERT [dbo].[staffs] ([branch_id], [id], [phone], [staff_code], [full_name]) VALUES (1, 2, N'0953087547', N'CBS-0002', N'Johnny Smith')\r\n","INSERT [dbo].[staffs] ([branch_id], [id], [phone], [staff_code], [full_name]) VALUES (1, 3, N'0989255534', N'CBS-0003', N'William Wilson')\r\n","INSERT [dbo].[staffs] ([branch_id], [id], [phone], [staff_code], [full_name]) VALUES (1, 4, N'0979067512', N'CBS-0004', N'Logan Williams')\r\n","INSERT [dbo].[staffs] ([branch_id], [id], [phone], [staff_code], [full_name]) VALUES (1, 5, N'0962164482', N'CBS-0005', N'Roy Williams')\r\n","INSERT [dbo].[staffs] ([branch_id], [id], [phone], [staff_code], [full_name]) VALUES (1, 6, N'0926576188', N'CBS-0006', N'Stephen M